head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.listRowCount = 0;
scwin.vProcGubun = '';
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.objParam = new Object();

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        lbl_info.hide();

        // 패널라운드처리
        $c.bns.BnsPanelToGroupBox(pnl_Item);
        $c.bns.BnsPanelToGroupBox(pnl_Input);

        // 호출파라미터설정
        scwin.setParam();

        // 연부과금 환급수수료 등록화면 조회
        const dsNm = 'BNS_ANFEE_REFND';
        let qryId = '';
        qryId = 'lds.stf.bnscommon.select.listAnfeeRefnd';
        let param;
        param += '&{P}V_BND_APPL_ID=' + scwin.objParam.BND_APPL_ID;
        param += '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.objParam.BND_LIST_PROCS_TP_CD;
        if (scwin.objParam.SCREN_ID === 'ULDBNS20100.gfm') {
            scwin.vProcGubun = 'MOD';
        } else {
            scwin.vProcGubun = 'IN';
        }
        param += '&{P}V_GUBUN=' + scwin.vProcGubun;
        $c.bns.fn_SearchBns('ULDBNS20101.xml', dts_DtlInfo, dsNm, qryId, param);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20101.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_DtlInfo_OnLoadError
 * @description dts_DtlInfo 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DtlInfo_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20101.dts_DtlInfo_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_DtlInfo_OnLoadCompleted
 * @description dts_DtlInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_DtlInfo_OnLoadCompleted = function(rowcount) {
    try {
        scwin.listRowCount = rowcount;
        // 담당자명이 비어 있는 경우, 사용자 이름을 보여줌
        if (txb_ChrgNm.getValue() === '') {
            txb_ChrgNm.setValue(js_emp_nm);
        }
        edt_BndAnulfee.RightMargin = 5;
        edt_PassProfit.RightMargin = 5;
        edt_RepayAmt.RightMargin = 5;
        if (dts_DtlInfo.getCellData(1, "BND_MKTACT_TP_CD") === '311') {
            lbl_BndDelDd.hide();
        } else if (dts_DtlInfo.getCellData(1, "BND_MKTACT_TP_CD") === '314') {
            lbl_AfchgRedmptDd.hide();
            edt_RedmptDd.setValue(edt_StrtDd.getValue());
            lbl_FstRedmptDd.hide(); // 최초상환일추가
            edt_FstRedmptDd.hide(); // 최초상환일추가

        } else {
            lbl_BndDelDd.hide();
            lbl_AfchgRedmptDd.hide();
            edt_RedmptDd.hide();
            lbl_FstRedmptDd.hide(); // 최초상환일추가
            edt_FstRedmptDd.hide(); // 최초상환일추가

            lbl_info.show("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20101.dts_DtlInfo_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_RefndDd_onclick
 * @description img_RefndDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_RefndDd_onclick = function() {
    try {
        popUpCalendar2(edt_RefndDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20101.img_RefndDd_onclick" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        if (scwin.listRowCount === 0) return;
        // 필수입력값 체크
        if (await scwin.inputCheck() === false) return;
        if (scwin.objParam.MKTACT_TP_CD === "314" || scwin.objParam.SCREN_ID === "ULDBNS20100.gfm") {
            scwin.save();
        } else {
            let prt = $c.frame.path("../");
            prt.dts_AnnulFee.ImportData(dts_DtlInfo.getRangeJSON(1, dts_DtlInfo.getRowCount(), false));
            let arrPar = new Array();
            arrPar[0] = {
                REG_YN: "Y"
            };
            scwin.fn_SetPar(arrPar);
            await $c.win.closePopup();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20101.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20101.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001"));
        let arrPar = new Array();
        arrPar[0] = {
            REG_YN: "Y"
        };
        scwin.fn_SetPar(arrPar);
        if (scwin.vProcGubun !== 'MOD') {
            // 연부과금환급에서 호출시 수정후 확인
            await $c.win.closePopup();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20101.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20101.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name edt_BndAnulfee_OnKillFocus
 * @description edt_BndAnulfee 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.edt_BndAnulfee_OnKillFocus = function() {
    try {
        edt_BndAnulfee.RightMargin = 5;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20101.edt_BndAnulfee_OnKillFocus" });
    }
};

/**
 * @method
 * @name edt_PassProfit_OnKillFocus
 * @description edt_PassProfit 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.edt_PassProfit_OnKillFocus = function() {
    try {
        edt_PassProfit.RightMargin = 5;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20101.edt_PassProfit_OnKillFocus" });
    }
};

/**
 * @method
 * @name edt_RepayAmt_OnKillFocus
 * @description edt_RepayAmt 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.edt_RepayAmt_OnKillFocus = function() {
    try {
        edt_RepayAmt.RightMargin = 5;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20101.edt_RepayAmt_OnKillFocus" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    let prt = $c.frame.path("../");
    if (prt !== undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar !== undefined) {
        let arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        scwin.objParam.BND_APPL_ID = arrPar[0].BND_APPL_ID;
        scwin.objParam.BND_LIST_PROCS_TP_CD = arrPar[0].BND_LIST_PROCS_TP_CD;
        scwin.objParam.MKTACT_TP_CD = arrPar[0].MKTACT_TP_CD;
        scwin.objParam.SCREN_ID = arrPar[0].SCREN_ID;
    }
};

/**
 * @method
 * @name inputCheck
 * @description 필수 입력 값을 체크한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.inputCheck = async function() {
    if (txb_BndApplId.getValue() === '') {
        await $c.win.alert("등록할 데이터가 없습니다.");
        return false;
    }
    if (edt_RefndDd.getValue() === '') {
        await $c.win.alert("[환급일]을 입력하십시오.");
        edt_RefndDd.focus();
        return false;
    }
    if ($c.bns.fn_CheckDateObj(edt_RefndDd, "환급일")) {
        return false;
    }
    // 자리수 체크
    if (!$c.stf.checkMaxLength(txb_ChrgNm, 80, '담당자')) return false;
    return true;
};

/**
 * @method
 * @name save
 * @description 연부과금 환급수수료 등록 (상장폐지(종목))
 * @returns {void}
 * @hidden N
 */
scwin.save = function() {
    if (!confirm("저장 하시겠습니까?")) return;
    let url = "/bns/ListBzAppl.do?method=createAnulfeeRefundFee";
    url += "&SCREN_ID=" + 'ULDBNS20101.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    url += "&PARENT_SCREN_ID=" + scwin.objParam.SCREN_ID;
    url += "&MKTACT_TP_CD=" + scwin.objParam.MKTACT_TP_CD;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo)";
    trs_Save.Post();
};
